import {
  HealthClient,
  IncidentsClient,
  MeClient,
  RunsClient,
  WeatherClient,
} from "../api/client";
import { CSRF_HEADER, isDemo, loginUrl } from "./session";

// The API clients, generated by NSwag from the API's OpenAPI document (web/src/api/client.ts; run `npm run api:client`
// after changing the API). This file adds what every call needs: a timeout, the CSRF header, the login when the
// session has ended, and one way of reporting failures.

const TIMEOUT_MS = 15_000;

/** The API answered with an error: its message (in Portuguese, shown to the user as is) and the HTTP status. */
export class ApiError extends Error {
  constructor(
    message: string,
    public readonly status: number,
  ) {
    super(message);
  }
}

/** No answer from the API, or an answer that is not the API's (service down, a proxy error page). */
export class ApiUnreachable extends Error {}

/**
 * The fetch the generated clients use. It turns every failure into ApiError or ApiUnreachable before the generated code
 * sees the response, so callers never get the generated client's own exceptions (some of which are not Errors).
 */
async function apiFetch(
  url: RequestInfo,
  init?: RequestInit,
): Promise<Response> {
  let res: Response;
  try {
    const headers = new Headers(init?.headers);
    for (const [k, v] of Object.entries(CSRF_HEADER)) headers.set(k, v);
    res = await fetch(url, {
      ...init,
      headers,
      signal: init?.signal ?? AbortSignal.timeout(TIMEOUT_MS),
    });
  } catch (e) {
    throw new ApiUnreachable(e instanceof Error ? e.message : String(e));
  }
  // The generated client asks for the one type each endpoint answers (JSON, or the raw raster bytes).
  const expected =
    new Headers(init?.headers).get("accept") ?? "application/json";
  const type = res.headers.get("content-type") ?? "";
  if (res.ok && type.startsWith(expected)) return res;
  // No session (never signed in, or it expired): outside the demo, go and sign in, then come back here.
  if (res.status === 401 && !isDemo()) location.assign(loginUrl());
  if (!type.startsWith("application/json"))
    throw new ApiUnreachable(`resposta inesperada (${res.status})`);
  const body: { error?: string } | null = await res.json().catch(() => null);
  throw new ApiError(body?.error ?? `erro ${res.status}`, res.status);
}

const http = { fetch: apiFetch };

export const healthApi = new HealthClient("", http);
export const incidentsApi = new IncidentsClient("", http);
export const meApi = new MeClient("", http);
export const runsApi = new RunsClient("", http);
export const weatherApi = new WeatherClient("", http);
